CREATE OR REPLACE FUNCTION public.record_credential_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
 audit_request_id text;
BEGIN
 IF NEW."providerId" <> 'credential' OR NEW.password IS NULL THEN RETURN NEW; END IF;
 IF TG_OP = 'UPDATE' AND NEW.password IS NOT DISTINCT FROM OLD.password THEN RETURN NEW; END IF;
 audit_request_id := current_setting('app.auth_request_id', true);
 IF audit_request_id IS NULL OR audit_request_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
   audit_request_id := gen_random_uuid()::text;
 END IF;
 IF TG_OP = 'UPDATE' AND OLD.password IS NOT NULL THEN
   INSERT INTO "PasswordHistory" ("userId","passwordHash","changedAt") VALUES (NEW."userId",OLD.password,(clock_timestamp() AT TIME ZONE 'UTC'));
   DELETE FROM "PasswordHistory" WHERE "userId" = NEW."userId" AND id NOT IN
     (SELECT id FROM "PasswordHistory" WHERE "userId" = NEW."userId" ORDER BY id DESC LIMIT 9);
 END IF;
 UPDATE "User" SET "passwordChangedAt" = (clock_timestamp() AT TIME ZONE 'UTC'), "updatedAt" = (clock_timestamp() AT TIME ZONE 'UTC') WHERE id = NEW."userId";
 DELETE FROM "PasswordDeferral" WHERE "userId" = NEW."userId";
 -- Audit the exact rows removed by this trigger, including sessions that the
 -- library's later adapter deletion can no longer see. Any insert failure
 -- aborts the credential update, proofs and every session removal together.
 WITH ended AS (
   DELETE FROM "Session" WHERE "userId" = NEW."userId" RETURNING id,"userId","activeCompanyId"
 )
 INSERT INTO "AuditEvent" (id,"actorId","tenantId",action,resource,"resourceId","requestId",detail,"createdAt")
 SELECT gen_random_uuid()::text,"userId","activeCompanyId",'session.ended','session',id,audit_request_id,
   '{"changedFields":[]}'::jsonb,(clock_timestamp() AT TIME ZONE 'UTC') FROM ended;
 DELETE FROM "Verification" WHERE value = NEW."userId";
 INSERT INTO "AuditEvent" (id,"actorId",action,resource,"resourceId","requestId",detail,"createdAt")
 VALUES (gen_random_uuid()::text,NEW."userId",CASE WHEN TG_OP = 'INSERT' THEN 'password.created' ELSE 'password.changed' END,
   'user',NEW."userId",audit_request_id,'{"changedFields":["password"]}'::jsonb,(clock_timestamp() AT TIME ZONE 'UTC'));
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.protect_activity_review_transition()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF ROW(NEW."tenantId",NEW."serviceId",NEW."auditEventId",NEW."recipientUserId",NEW."requesterId",NEW."recipientId",NEW."title",NEW."createdAt") IS DISTINCT FROM ROW(OLD."tenantId",OLD."serviceId",OLD."auditEventId",OLD."recipientUserId",OLD."requesterId",OLD."recipientId",OLD."title",OLD."createdAt") OR NEW."version"<>OLD."version"+1 THEN RAISE EXCEPTION 'immutable review scope or invalid version' USING ERRCODE='23514'; END IF;
 IF OLD."destructionStatus" IN ('destroyed','kept') THEN RAISE EXCEPTION 'terminal review destruction state' USING ERRCODE='23514'; END IF;
 IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT ((OLD."status"='requested' AND NEW."status" IN ('responded','cancelled')) OR (OLD."status"='responded' AND NEW."status" IN ('resolved','cancelled'))) THEN RAISE EXCEPTION 'invalid review transition' USING ERRCODE='23514'; END IF;
 IF NEW."destructionStatus" IS DISTINCT FROM OLD."destructionStatus" AND NOT ((OLD."destructionStatus"='none' AND NEW."destructionStatus"='awaiting') OR (OLD."destructionStatus"='awaiting' AND NEW."destructionStatus" IN ('destroyed','kept','none'))) THEN RAISE EXCEPTION 'invalid review destruction transition' USING ERRCODE='23514'; END IF;
 IF NEW."status" NOT IN ('resolved','cancelled') AND (NEW."retentionUntil" IS NOT NULL OR NEW."destructionStatus"<>'none' OR NEW."destroyedAt" IS NOT NULL OR NEW."destroyApproverId" IS NOT NULL) THEN RAISE EXCEPTION 'destruction requires closed review' USING ERRCODE='23514'; END IF;
 IF NEW."destructionStatus"='destroyed' AND (NEW."destroyedAt" IS NULL OR NEW."destroyApproverId" IS NULL) THEN RAISE EXCEPTION 'destroyed review requires evidence' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.guard_active_account_reference()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE account_status text;
BEGIN
  IF TG_TABLE_NAME = 'Membership' THEN
    IF NEW.status <> 'active' THEN RETURN NEW; END IF;
  END IF;
  SELECT status INTO account_status FROM "User" WHERE id = NEW."userId" FOR SHARE;
  IF account_status <> 'active' THEN
    RAISE EXCEPTION 'ACCOUNT_UNAVAILABLE' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.protect_last_mfa_owner_account()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE company_id TEXT;
BEGIN
  IF OLD."twoFactorEnabled" AND OLD.status='active' AND (NOT NEW."twoFactorEnabled" OR NEW.status<>'active') THEN
    FOR company_id IN SELECT m."tenantId" FROM "Membership" m JOIN "Company" c ON c.id=m."tenantId" JOIN "SecurityPolicy" p ON p."tenantId"=c.id
      WHERE m."userId"=OLD.id AND m.role='owner' AND m.status='active' AND m."accessKind"='direct' AND c.status='active' AND p."requireMfa" ORDER BY m."tenantId"
    LOOP
      PERFORM id FROM "Company" WHERE id=company_id FOR UPDATE;
      IF NOT EXISTS(SELECT 1 FROM "Membership" m JOIN "User" u ON u.id=m."userId" WHERE m."tenantId"=company_id AND m."userId"<>OLD.id AND m.role='owner' AND m.status='active' AND m."accessKind"='direct' AND u.status='active' AND u."emailVerified" AND u."twoFactorEnabled")
      THEN RAISE EXCEPTION 'LAST_MFA_OWNER_REQUIRED' USING ERRCODE='23514'; END IF;
    END LOOP;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.invalidate_export_access()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE row_data jsonb; actor_id text; tenant_id text; service_id text;
BEGIN
  IF TG_OP='INSERT' THEN row_data:=to_jsonb(NEW); ELSE row_data:=to_jsonb(OLD); END IF;
  tenant_id:=row_data->>'tenantId';
  IF TG_TABLE_NAME='User' THEN actor_id:=row_data->>'id';
  ELSIF TG_TABLE_NAME='Company' THEN tenant_id:=row_data->>'id';
  ELSIF TG_TABLE_NAME='Service' THEN service_id:=row_data->>'id';
  ELSIF TG_TABLE_NAME='Membership' THEN actor_id:=row_data->>'userId';
  ELSIF TG_TABLE_NAME='ExpertAssignment' THEN actor_id:=row_data->>'expertUserId';
  ELSIF TG_TABLE_NAME='ServiceGrant' THEN
    SELECT "userId" INTO actor_id FROM "Membership" WHERE id=row_data->>'memberId' AND "tenantId"=tenant_id;
    service_id:=row_data->>'serviceId';
  ELSIF TG_TABLE_NAME='ExpertAssignmentService' THEN
    SELECT "expertUserId" INTO actor_id FROM "ExpertAssignment" WHERE id=row_data->>'assignmentId' AND "tenantId"=tenant_id;
    service_id:=row_data->>'serviceId';
  END IF;
  PERFORM erase_export_jobs(ARRAY(SELECT id FROM "ExportJob" WHERE (tenant_id IS NULL OR "tenantId"=tenant_id) AND (actor_id IS NULL OR "requesterId"=actor_id) AND (service_id IS NULL OR "serviceId"=service_id)),'ACCESS_CHANGED');
  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $function$

